import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('clipdup_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
function setup(sim,kind){sim.state.scenes.push({...sim.state.scenes[0],ref:'scene:scene-2',objectIdentity:'simulator:scene:scene-2',index:1,name:'Scene 2'});sim.state.tracks[0].clipSlots.push({...sim.state.tracks[0].clipSlots[0],ref:'clip-slot:track-1:1',objectIdentity:'simulator:clip-slot:track-1:1',sceneIndex:1,clipRef:null,empty:true});if(kind.endsWith('audio'))Object.assign(sim.state.tracks[0].clips[0],{kind:'audio',notes:[],filePath:'/mock/sample.wav'});}
const rows=[];for(const action of ['preview','apply']){const valid=action==='preview'?{clipRef:'clip:clip-1',targetTrackRef:'track:track-1',targetSceneIndex:1}:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of (action==='preview'?['clipRef','targetTrackRef','targetSceneIndex','arrangementPosition']:Object.keys(valid))){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,0.5,1,100001,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const sim=new DeterministicLiveSimulator();setup(sim,'session-midi');const host=new McpHost(sim);let result;try{result=clean(await host[action==='preview'?'liveClipDuplicatePreviewAsync':'liveClipDuplicateApplyAsync'](1,args));}catch(e){result={error:e.message};}rows.push({action,args,result});}}
const workflows=[];for(const kind of ['session-midi','arrangement-midi','session-audio','arrangement-audio'])for(const scenario of ['normal','expire','epoch','identity-edit','source-content','target-identity','target-occupied','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-invalid-identity','apply-invalid-fingerprint','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-content','undo-epoch']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();setup(sim,kind);let fault='',fired=false,afterInvoke=false;if(scenario==='missing-identity')delete sim.state.tracks[0].clips[0].objectIdentity;
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&['apply-invalid-identity','apply-invalid-fingerprint'].includes(fault)){fired=true;result[fault.endsWith('identity')?'objectIdentity':'createdFingerprint']='';}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const args={clipRef:'clip:clip-1',...(kind.startsWith('arrangement')?{arrangementPosition:8}:{targetTrackRef:'track:track-1',targetSceneIndex:1})};const preview=await host.liveClipDuplicatePreviewAsync(1,args);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveClipDuplicateApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.tracks[0].clips[0].objectIdentity='other';if(scenario==='source-content')sim.state.tracks[0].clips[0].name='Manual';if(scenario==='target-identity')sim.state.tracks[0].clipSlots[1].objectIdentity='other';if(scenario==='target-occupied')sim.state.tracks[0].clipSlots[1].clipRef='clip:external';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
const created=kind.startsWith('arrangement')?sim.state.arrangementClips.map(r=>r.clip).find(c=>c.ref===record.created?.ref):sim.state.tracks.flatMap(t=>t.clips).find(c=>c.ref===record.created?.ref);if(created&&scenario==='undo-other-identity')created.objectIdentity='other';if(created&&scenario==='undo-other-content')created.name='Manual';if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-clip-duplicate-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
